local Knitter = {}
local PRODUCTS = {
    plain_wool_mitten = { name = "Preproste volnene rokavice", woolCost = 2, time = 3, cost = 30, warmth = 25, happiness = 1, description = "Preproste volnene rokavice za zimo." },
    cable_knit_scarf = { name = "Prepleten šal", woolCost = 3, time = 5, cost = 80, warmth = 40, happiness = 1, prestige = 1, description = "Prepleten šal za trgovce." },
    silk_blend_stocking = { name = "Svilo-lanana nogavica", woolCost = 2, silkCost = 1, time = 7, cost = 220, warmth = 35, happiness = 2, prestige = 4, description = "Svilo-lanana nogavica za plemiče." },
    silver_thread_sweater = { name = "Srebrnonitni pulover", woolCost = 3, silkCost = 1, silverCost = 1, time = 11, cost = 540, warmth = 60, happiness = 3, prestige = 12, description = "Pulover s srebrno nitjo za visoke plemiče." },
    gold_embroidered_shawl = { name = "Zlato vezen šal", woolCost = 3, silkCost = 2, goldCost = 1, silverCost = 1, time = 15, cost = 1300, warmth = 70, happiness = 5, prestige = 25, description = "Šal z zlato vezavo za visoko plemstvo." },
    royal_ermine_trimmed_cape = { name = "Kraljevski hermelinov plašč", woolCost = 4, silkCost = 3, goldCost = 2, silverCost = 2, jewelCost = 1, pearlCost = 1, time = 22, cost = 3300, warmth = 90, happiness = 11, prestige = 55, description = "Veliki kraljevski plašč z hermelinom in biseri za kronanje." },
}
local BUILDINGS = {
    knitting_cottage = { name = "Pletenjska koča", cost = { gold = 180, wood = 100, stone = 60, wool = 6 }, upkeep = 4, qualityBonus = 5 },
    knitting_loft = { name = "Pletenjska podstrešje", cost = { gold = 720, wood = 220, stone = 200, silk = 6, wool = 8 }, upkeep = 16, qualityBonus = 18 },
    fine_knit_atelier = { name = "Finopletni atelje", cost = { gold = 2200, wood = 340, stone = 480, silver = 28, silk = 8 }, upkeep = 50, qualityBonus = 30 },
    royal_knitting_palace = { name = "Kraljevska pletenjska palača", cost = { gold = 9200, wood = 580, stone = 720, gold = 55, jewel = 14 }, upkeep = 185, qualityBonus = 55, prestigeBonus = 50 },
}
Knitter.woolStock = 18; Knitter.silkStock = 12; Knitter.silverStock = 6; Knitter.goldStock = 6; Knitter.jewelStock = 4; Knitter.pearlStock = 4
Knitter.productStock = {}; Knitter.buildings = {}; Knitter.maker = nil; Knitter.activeMaking = {}; Knitter.totalProducts = 0; Knitter.dayTimer = 0
function Knitter.init() Knitter.woolStock=18; Knitter.silkStock=12; Knitter.silverStock=6; Knitter.goldStock=6; Knitter.jewelStock=4; Knitter.pearlStock=4; Knitter.productStock={}; Knitter.buildings={}; Knitter.maker=nil; Knitter.activeMaking={}; Knitter.totalProducts=0; Knitter.dayTimer=0; print("[Knitter] Royal Knitter System initialized (6 products, 4 buildings)") end
function Knitter.hireMaker(n,s) s=s or math.random(55,90); local c=420+s*11; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; Knitter.maker={name=n or ("Pletar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Pletar najet: %s (spretnost: %d)",Knitter.maker.name,s),"success") end; return true end
function Knitter.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function Knitter.build(id) local ok,e=Knitter.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(Knitter.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function Knitter.getQualityBonus() local b=0; for _,bd in ipairs(Knitter.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function Knitter.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.woolCost and Knitter.woolStock<(d.woolCost or 0) then return false,"Premalo volne" end; if d.silkCost and Knitter.silkStock<(d.silkCost or 0) then return false,"Premalo svile" end; if d.silverCost and Knitter.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and Knitter.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and Knitter.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and Knitter.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #Knitter.buildings==0 then return false,"Potrebna pletenjska koča" end; if not Knitter.maker then return false,"Potreben pletar" end; return true end
function Knitter.make(pt,qty) qty=qty or 1; local ok,e=Knitter.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.woolCost then Knitter.woolStock=Knitter.woolStock-d.woolCost*qty end; if d.silkCost then Knitter.silkStock=Knitter.silkStock-d.silkCost*qty end; if d.silverCost then Knitter.silverStock=Knitter.silverStock-d.silverCost*qty end; if d.goldCost then Knitter.goldStock=Knitter.goldStock-d.goldCost*qty end; if d.jewelCost then Knitter.jewelStock=Knitter.jewelStock-d.jewelCost*qty end; if d.pearlCost then Knitter.pearlStock=Knitter.pearlStock-d.pearlCost*qty end; local t=d.time; if Knitter.maker then t=math.max(1,t-math.floor(Knitter.maker.skill/14)) end; table.insert(Knitter.activeMaking,{id="knit_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,warmth=d.warmth or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Pletenje: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function Knitter.completeMaking(m) local q=1.0+(Knitter.getQualityBonus()/100); if Knitter.maker then q=q+(Knitter.maker.skill/160) end; q=math.min(2.2,q); Knitter.productStock[m.productType]=(Knitter.productStock[m.productType] or 0)+m.quantity; Knitter.totalProducts=Knitter.totalProducts+m.quantity; if m.warmth>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+math.floor(m.warmth/30)) end; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if Knitter.maker then Knitter.maker.itemsMade=Knitter.maker.itemsMade+m.quantity; if math.random()<0.25 then Knitter.maker.skill=math.min(100,Knitter.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Pletenina gotova: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"knit.completed",{productName=m.productName,warmth=m.warmth,prestige=m.prestige,happiness=m.happiness}) end end
function Knitter.update(dt) if not _G.state then return end; Knitter.dayTimer=Knitter.dayTimer+dt; if Knitter.dayTimer>=30 then Knitter.dayTimer=0; for i=#Knitter.activeMaking,1,-1 do local m=Knitter.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then Knitter.completeMaking(m); table.remove(Knitter.activeMaking,i) end end; local tu=0; for _,bd in ipairs(Knitter.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if Knitter.maker then tu=tu+10 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function Knitter.getStats() return {woolStock=Knitter.woolStock,silkStock=Knitter.silkStock,silverStock=Knitter.silverStock,goldStock=Knitter.goldStock,jewelStock=Knitter.jewelStock,pearlStock=Knitter.pearlStock,productStock=Knitter.productStock,numBuildings=#Knitter.buildings,hasMaker=Knitter.maker~=nil,makerName=Knitter.maker and Knitter.maker.name or "—",makerSkill=Knitter.maker and Knitter.maker.skill or 0,activeMaking=#Knitter.activeMaking,totalProducts=Knitter.totalProducts} end
return Knitter
